<?php
trait CxScheduling {
    private function scheduleRow($company,$id) {
        $this->permission($company);$r=$this->run('SELECT * FROM Cx_Programacion WHERE IdEmpresa=? AND IdProgramacion=?',[$company,cxId($id)])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new CxError('Programación no disponible.',404);$r['Instantanea']=json_decode($r['Instantanea'],true);$r['cargas']=$this->run("SELECT * FROM Cx_CargaProgramada WHERE IdEmpresa=? AND IdProgramacion=? AND RevisionPlan=? ORDER BY Secuencia",[$company,$id,$r['Revision']])->fetchAll(PDO::FETCH_ASSOC);foreach($r['cargas'] as &$c)$c['Instantanea']=json_decode($c['Instantanea'],true);unset($c);$r['responsables']=$this->run('SELECT * FROM Cx_ProgramacionResponsable WHERE IdEmpresa=? AND IdProgramacion=? ORDER BY Area',[$company,$id])->fetchAll(PDO::FETCH_ASSOC);return $r;
    }
    public function schedules($company,$day) {
        $this->permission($company);$day=cxDate($day);$rows=$this->run("SELECT p.*,o.Anio AS PedidoAnio,o.Numero AS PedidoNumero,(SELECT COUNT(*) FROM Cx_CargaProgramada c WHERE c.IdEmpresa=p.IdEmpresa AND c.IdProgramacion=p.IdProgramacion AND c.RevisionPlan=p.Revision) AS Cargas FROM Cx_Programacion p JOIN Cx_Pedido o ON o.IdEmpresa=p.IdEmpresa AND o.IdPedido=p.IdPedido WHERE p.IdEmpresa=? AND p.Inicio<? AND COALESCE(p.Fin,p.Inicio)>=? ORDER BY p.Inicio,p.IdProgramacion LIMIT 250",[$company,(new DateTimeImmutable($day))->modify('+1 day')->format('Y-m-d').' 00:00:00',$day.' 00:00:00'])->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$row){$row['StockEstado']='POR_VALIDAR';if(in_array($row['Estado'],['CANCELADA','REPROGRAMADA'],true)){$row['StockEstado']='SIN_COMPROMISO';continue;}if(!$row['IdDisenoVersion'])continue;$d=$this->design($company,$row['IdDisenoVersion']);if($d['Estado']!=='APROBADA')continue;$row['StockEstado']='SUFICIENTE_NOMINAL';foreach($d['componentes'] as $c){$stock=$this->materialStock($company,$row['IdAlmacen'],$c['IdProducto']);$own=$this->run('SELECT CantidadNominal FROM Cx_ReservaInsumo WHERE IdEmpresa=? AND IdProgramacion=? AND IdProducto=? AND Activo=1',[$company,$row['IdProgramacion'],$c['IdProducto']])->fetchColumn();if(bccomp(bcmul($c['CantidadNominal'],$row['Cantidad'],6),bcadd($stock['disponible'],$own?:'0',6),6)>0)$row['StockEstado']='FALTANTE';}}unset($row);return $rows;
    }
    private function scheduleEquipment($company,$id,$type) {
        if(!$id)return null;$r=$this->run('SELECT * FROM Cx_Equipo WHERE IdEmpresa=? AND IdEquipo=? AND Tipo=?',[$company,cxId($id),$type])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new CxError('Equipo no disponible para esta empresa.',404);return $r;
    }
    private function scheduleLoads($quantity,$start,$plant,$mixer,$driver,array $times) {
        $loads=[];$end=null;if($start&&$plant&&$mixer&&$driver&&!in_array(null,$times,true)){
            $remaining=$quantity;$cursor=new DateTimeImmutable($start,new DateTimeZone('America/Lima'));$n=0;$capacity=(string)$mixer['CapacidadUtil'];if(bccomp($capacity,'0',4)<=0)throw new CxError('Configure la capacidad útil del mixer.');
            while(bccomp($remaining,'0',4)>0){if(++$n>200)throw new CxError('Divida este volumen entre varias programaciones; excede 200 cargas.');$volume=bccomp($remaining,$capacity,4)>0?$capacity:$remaining;$loadEnd=$cursor->modify('+'.$plant['MinCarga'].' minutes');$arrival=$loadEnd->modify('+'.$times['minIda'].' minutes');$dischargeEnd=$arrival->modify('+'.$times['minDescarga'].' minutes');$return=$dischargeEnd->modify('+'.$times['minRetorno'].' minutes');$loads[]=['secuencia'=>$n,'cantidad'=>bcadd($volume,'0',4),'inicio'=>$cursor->format('Y-m-d H:i:s'),'finCarga'=>$loadEnd->format('Y-m-d H:i:s'),'llegada'=>$arrival->format('Y-m-d H:i:s'),'finDescarga'=>$dischargeEnd->format('Y-m-d H:i:s'),'retorno'=>$return->format('Y-m-d H:i:s')];$cursor=$return;$remaining=bcsub($remaining,$volume,4);}$end=$cursor->format('Y-m-d H:i:s');
        }
        return ['cargas'=>$loads,'fin'=>$end];
    }
    private function scheduleInput($company,array $p) {
        $order=$this->order($company,$p['idPedido']??0);if($order['Estado']!=='ABIERTO')throw new CxError('El pedido no está abierto para programar.');$line=null;foreach($order['partidas'] as $r)if((int)$r['IdPedidoPartida']===(int)($p['idPedidoPartida']??0))$line=$r;if(!$line||$line['Tipo']!=='CONCRETO')throw new CxError('Seleccione una partida de concreto del pedido; un servicio no suma volumen de concreto.');
        $warehouse=$this->reference($company,'ALMACEN',$p['idAlmacen']??0);$start=cxDateTime($p['inicio']??'');if($start<cxNow())throw new CxError('La programación debe tener una fecha y hora futuras.');$quantity=cxDec($p['cantidad']??'',2,true);$element=cxText($p['elemento']??'',180,true);$slump=cxDec($p['slump']??'',2,true);$unit=cxChoice($p['unidadSlump']??'',['pulg','mm'],'la unidad del slump');$discharge=cxChoice($p['descarga']??'',['BOMBEADO','CAIDA_LIBRE'],'la descarga');
        $plant=$this->run('SELECT * FROM Cx_PlantaOperacion WHERE IdEmpresa=? AND IdAlmacen=?',[$company,$warehouse])->fetch(PDO::FETCH_ASSOC);$mixer=$this->scheduleEquipment($company,$p['idMixer']??null,'MIXER');$pump=$this->scheduleEquipment($company,$p['idBomba']??null,'BOMBA');$design=empty($p['idDisenoVersion'])?null:$this->design($company,$p['idDisenoVersion']);$driver=empty($p['conductor'])?null:$this->opUser($company,cxText($p['conductor'],100,true),'DESPACHO');
        $times=[];foreach(['minIda','minDescarga','minRetorno'] as $key){$v=$p[$key]??null;if($v===null||$v==='')$times[$key]=null;else{if(filter_var($v,FILTER_VALIDATE_INT)===false||(int)$v<($key==='minDescarga'?1:0)||(int)$v>10080)throw new CxError('Revise los minutos de ida, descarga y retorno.');$times[$key]=(int)$v;}}
        $responsibles=['PROGRAMACION'=>$this->opUser($company,$this->user,'PROGRAMACION')];foreach(['ALMACEN','TECNICA','PLANTA','DESPACHO'] as $area)if(!empty($p['responsables'][$area]))$responsibles[$area]=$this->opUser($company,cxText($p['responsables'][$area],100,true),$area);
        $calculated=$this->scheduleLoads($quantity,$start,$plant,$mixer,$driver,$times);$loads=$calculated['cargas'];$end=$calculated['fin'];
        return ['pedido'=>$order,'partida'=>$line,'almacen'=>$warehouse,'inicio'=>$start,'fin'=>$end,'cantidad'=>$quantity,'elemento'=>$element,'slump'=>$slump,'unidadSlump'=>$unit,'descarga'=>$discharge,'planta'=>$plant?:null,'mixer'=>$mixer,'bomba'=>$pump,'diseno'=>$design,'conductor'=>$driver,'tiempos'=>$times,'responsables'=>$responsibles,'cargas'=>$loads,'observaciones'=>cxText($p['observaciones']??'',4000)];
    }
    public function saveSchedule($company,array $p) {
        $this->operational($company,'PROGRAMACION');return $this->atomic($company,function()use($company,$p){return $this->idempotency($company,'PROGRAMAR',$p['idempotencia']??'',[$p,$this->user],function()use($company,$p){
            if(!empty($p['id'])&&!empty($p['idAnterior']))throw new CxError('Elija editar o reprogramar, no ambas acciones.');$data=$this->scheduleInput($company,$p);$id=empty($p['id'])?null:cxId($p['id']);$previous=empty($p['idAnterior'])?null:cxId($p['idAnterior']);$old=null;$revision=1;
            if($id||$previous){$old=$this->scheduleRow($company,$id?:$previous);if((int)$old['Revision']!==(int)($p['revision']??0))throw new CxError('La programación cambió. Actualice antes de guardar.',409);if((int)$old['IdPedido']!==(int)$data['pedido']['IdPedido'])throw new CxError('No cambie el pedido de una programación.');if((int)$old['IdPedidoPartida']!==(int)$data['partida']['IdPedidoPartida'])throw new CxError('No cambie la partida de esta programación; cancele y cree otra.');if($id&&$old['Estado']!=='BORRADOR')throw new CxError('Use Reprogramar para conservar el historial de la agenda confirmada.',409);$this->assertUnstarted($old);if($id)$revision=(int)$old['Revision']+1;}
            $this->run('SELECT IdPedidoPartida FROM Cx_PedidoPartida WHERE IdEmpresa=? AND IdPedidoPartida=? FOR UPDATE',[$company,$data['partida']['IdPedidoPartida']]);$reserved=$this->run("SELECT COALESCE(SUM(Cantidad),0) FROM Cx_Programacion WHERE IdEmpresa=? AND IdPedidoPartida=? AND Estado IN ('BORRADOR','CONFIRMADA','EN_PREPARACION','EN_CURSO','ATENDIDA') AND IdProgramacion<>?",[$company,$data['partida']['IdPedidoPartida'],$id?:($previous?:0)])->fetchColumn();$available=bcsub($data['partida']['CantidadContratada'],$reserved,4);if(bccomp($data['cantidad'],$available,4)>0)throw new CxError('Volumen pendiente insuficiente para esa partida. Disponible para programar: '.cxOpNumber($available).' m³.');
            if($previous){if(!in_array($old['Estado'],['BORRADOR','CONFIRMADA'],true))throw new CxError('No se puede reprogramar este estado.',409);$this->releaseSchedule($company,$old['IdProgramacion'],'REPROGRAMADA');}
            $snapshot=['solicitud'=>$p,'datos'=>$data,'autor'=>['usuario'=>$this->user,'area'=>'PROGRAMACION'],'fecha'=>cxNow()];unset($snapshot['datos']['pedido']['partidas']);
            $args=[$data['almacen'],$data['inicio'],$data['fin'],$data['cantidad'],$data['elemento'],$data['slump'],$data['unidadSlump'],$data['descarga'],$data['diseno']['IdDisenoVersion']??null,$data['mixer']['IdEquipo']??null,$data['conductor']['usuario']??null,$data['bomba']['IdEquipo']??null,$data['tiempos']['minIda'],$data['tiempos']['minDescarga'],$data['tiempos']['minRetorno'],$data['observaciones'],cxJson($snapshot)];
            if($id){$this->run("UPDATE Cx_CargaProgramada SET Estado='SUSTITUIDA' WHERE IdEmpresa=? AND IdProgramacion=?",[$company,$id]);$this->run('UPDATE Cx_Programacion SET IdAlmacen=?,Inicio=?,Fin=?,Cantidad=?,Elemento=?,Slump=?,UnidadSlump=?,Descarga=?,IdDisenoVersion=?,IdMixer=?,Conductor=?,IdBomba=?,MinIda=?,MinDescarga=?,MinRetorno=?,Observaciones=?,Instantanea=?,Revision=Revision+1 WHERE IdEmpresa=? AND IdProgramacion=?',array_merge($args,[$company,$id]));$this->run('DELETE FROM Cx_ProgramacionResponsable WHERE IdEmpresa=? AND IdProgramacion=?',[$company,$id]);}
            else{$year=(int)substr($data['inicio'],0,4);$number=$this->nextNumber($company,'PG',$year);$this->run('INSERT INTO Cx_Programacion(IdEmpresa,IdPedido,IdPedidoPartida,Anio,Numero,IdAlmacen,Inicio,Fin,Cantidad,Elemento,Slump,UnidadSlump,Descarga,IdDisenoVersion,IdMixer,Conductor,IdBomba,MinIda,MinDescarga,MinRetorno,Observaciones,Instantanea,IdAnterior,UsuarioReg,FechaReg) VALUES('.implode(',',array_fill(0,25,'?')).')',array_merge([$company,$data['pedido']['IdPedido'],$data['partida']['IdPedidoPartida'],$year,$number],$args,[$previous,$this->user,cxNow()]));$id=(int)$this->db->lastInsertId();}
            foreach($data['responsables'] as $area=>$u)$this->run('INSERT INTO Cx_ProgramacionResponsable(IdEmpresa,IdProgramacion,Area,Usuario,Nombre) VALUES(?,?,?,?,?)',[$company,$id,$area,$u['usuario'],$u['nombre']]);
            foreach($data['cargas'] as $c)$this->run('INSERT INTO Cx_CargaProgramada(IdEmpresa,IdProgramacion,RevisionPlan,Secuencia,CantidadNominal,Inicio,FinCarga,Llegada,FinDescarga,Retorno,Instantanea) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$company,$id,$revision,$c['secuencia'],$c['cantidad'],$c['inicio'],$c['finCarga'],$c['llegada'],$c['finDescarga'],$c['retorno'],cxJson(['mixer'=>$data['mixer'],'conductor'=>$data['conductor'],'diseno'=>$data['diseno'],'planta'=>$data['planta'],'volumenNominal'=>$c['cantidad']])]);
            $this->audit($company,'programacion',$id,$previous?'REPROGRAMAR':'GUARDAR_BORRADOR',$old,['cantidad'=>$data['cantidad'],'responsables'=>$data['responsables'],'cargas'=>count($data['cargas'])],cxText($p['motivo']??'Programación desde pedido aceptado',1000,true));return ['id'=>$id,'estado'=>'BORRADOR','cargas'=>count($data['cargas'])];
        });});
    }
    private function assertUnstarted(array $plan) {
        foreach($plan['cargas'] as $c)if(!in_array($c['Estado'],['PROPUESTA','PROGRAMADA','CANCELADA','SUSTITUIDA'],true))throw new CxError('Hay una carga iniciada. Registre una incidencia; no se liberan sus materiales mediante una edición.',409);
    }
    private function releaseSchedule($company,$id,$state) {
        $this->run('UPDATE Cx_Programacion SET Estado=? WHERE IdEmpresa=? AND IdProgramacion=?',[$state,$company,$id]);$this->run('UPDATE Cx_ReservaRecurso SET Activo=0 WHERE IdEmpresa=? AND IdProgramacion=?',[$company,$id]);$this->run('UPDATE Cx_ReservaInsumo SET Activo=0 WHERE IdEmpresa=? AND IdProgramacion=?',[$company,$id]);$this->run("UPDATE Cx_CargaProgramada SET Estado='CANCELADA' WHERE IdEmpresa=? AND IdProgramacion=? AND Estado IN ('PROPUESTA','PROGRAMADA')",[$company,$id]);
    }
    private function planBookings(array $p) {
        $rows=[];foreach($p['cargas'] as $c){$rows[]=['PLANTA',(string)$p['IdAlmacen'],$c['Inicio'],$c['FinCarga'],$c['IdCarga']];$rows[]=['MIXER',(string)$p['IdMixer'],$c['Inicio'],$c['Retorno'],$c['IdCarga']];$rows[]=['CONDUCTOR',$p['Conductor'],$c['Inicio'],$c['Retorno'],$c['IdCarga']];if($p['IdBomba'])$rows[]=['BOMBA',(string)$p['IdBomba'],$c['Llegada'],$c['FinDescarga'],$c['IdCarga']];}return $rows;
    }
    private function scheduleRequirements($company,array $p) {
        $errors=[];if(in_array($p['Estado'],['CANCELADA','REPROGRAMADA'],true))return ['pendientes'=>[],'materiales'=>[]];$plant=$this->run('SELECT * FROM Cx_PlantaOperacion WHERE IdEmpresa=? AND IdAlmacen=?',[$company,$p['IdAlmacen']])->fetch(PDO::FETCH_ASSOC);if(!$plant||!isset($p['Instantanea']['datos']['planta']['Revision'])||(int)$plant['Revision']!==(int)$p['Instantanea']['datos']['planta']['Revision'])$errors[]='La configuración de planta cambió o falta; editar y recalcular cargas.';if(!$this->run('SELECT IdAlmacen FROM Lo_Almacen WHERE IdAlmacen=? AND COALESCE(Anulado+0,0)=0',[$p['IdAlmacen']])->fetchColumn())$errors[]='Almacén de planta inactivo.';if($p['Inicio']&&$p['Inicio']<cxNow()&&$p['Estado']==='BORRADOR')$errors[]='La hora solicitada ya pasó; reprogramar.';if(!$p['cargas'])$errors[]='Configure capacidad de planta/mixer, conductor y minutos para proponer las cargas.';
        foreach(['PROGRAMACION','ALMACEN','TECNICA','PLANTA','DESPACHO'] as $area){$r=null;foreach($p['responsables'] as $u)if($u['Area']===$area)$r=$u;if(!$r)$errors[]='Asignar responsable del área '.$area.'.';else try{$this->opUser($company,$r['Usuario'],$area);}catch(CxError $e){$errors[]=$e->getMessage();}}
        if(!$this->run('SELECT IdPedido FROM Cx_AutorizacionAgenda WHERE IdEmpresa=? AND IdPedido=?',[$company,$p['IdPedido']])->fetchColumn())$errors[]='Falta autorización comercial de agenda. No se presume cobro o crédito aprobado.';
        $orderState=$this->run('SELECT Estado FROM Cx_Pedido WHERE IdEmpresa=? AND IdPedido=?',[$company,$p['IdPedido']])->fetchColumn();if($orderState!=='ABIERTO')$errors[]='El pedido ya no está abierto para suministro.';$d=null;if(!$p['IdDisenoVersion'])$errors[]='Asignar una receta aprobada.';else{$d=$this->design($company,$p['IdDisenoVersion']);if($d['Estado']!=='APROBADA')$errors[]='La receta no está aprobada.';$line=$this->run('SELECT * FROM Cx_PedidoPartida WHERE IdEmpresa=? AND IdPedidoPartida=?',[$company,$p['IdPedidoPartida']])->fetch(PDO::FETCH_ASSOC);$source=json_decode($line['Instantanea'],true);$spec=$source['Instantanea']['especificacion']??[];if(!empty($spec['Resistencia'])&&(bccomp($d['Resistencia'],$spec['Resistencia'],4)!==0||$d['UnidadResistencia']!==($spec['UnidadResistencia']??'')))$errors[]='La resistencia del diseño difiere de la especificación aceptada.';if(in_array($spec['Descarga']??'',['BOMBEADO','CAIDA_LIBRE'],true)&&$p['Descarga']!==$spec['Descarga'])$errors[]='La descarga debe respetar lo contratado en la proforma.';if(in_array($spec['UnidadSlump']??'',['pulg','mm'],true)&&$p['UnidadSlump']!==$spec['UnidadSlump'])$errors[]='La unidad de slump debe respetar lo contratado; no se aplica conversión supuesta.';if(isset($spec['SlumpMin'],$spec['SlumpMax'])&&(bccomp($p['Slump'],$spec['SlumpMin'],4)<0||bccomp($p['Slump'],$spec['SlumpMax'],4)>0))$errors[]='El slump está fuera del rango contratado en la proforma.';if((int)$d['IdProducto']!==(int)$line['IdProducto']||(int)$d['IdAlmacen']!==(int)$p['IdAlmacen'])$errors[]='La receta no corresponde al producto o planta del pedido.';if($d['UnidadSlump']!==$p['UnidadSlump']||bccomp($p['Slump'],$d['SlumpMin'],4)<0||bccomp($p['Slump'],$d['SlumpMax'],4)>0||$d['Descarga']!==$p['Descarga'])$errors[]='Slump o descarga incompatibles con la receta.';if(!empty($spec['EdadDias'])&&(int)$spec['EdadDias']!==(int)$d['EdadDias'])$errors[]='La edad del diseño no coincide con la prestación contratada.';}
        foreach([['IdMixer','MIXER'],['IdBomba','BOMBA']] as $pair){if(!$p[$pair[0]]){if($pair[0]==='IdMixer'||$p['Descarga']==='BOMBEADO')$errors[]='Asignar '.$pair[1].'.';continue;}$e=$this->scheduleEquipment($company,$p[$pair[0]],$pair[1]);if($pair[0]==='IdMixer'){foreach($p['cargas'] as $load)if(bccomp($load['CantidadNominal'],$e['CapacidadUtil'],4)>0)$errors[]='La carga supera la capacidad actual del mixer; editar y recalcular.';if((int)($p['Instantanea']['datos']['mixer']['Revision']??0)!==(int)$e['Revision'])$errors[]='El mixer cambió; editar y recalcular las cargas.';}if(!(int)$e['Activo']||$e['DocumentoHasta']<substr($p['Fin']?:$p['Inicio'],0,10))$errors[]=$e['Codigo'].': equipo inactivo o documentos vencidos.';if($this->run('SELECT IdBloqueo FROM Cx_EquipoBloqueo WHERE IdEmpresa=? AND IdEquipo=? AND Inicio<? AND Fin>? LIMIT 1',[$company,$e['IdEquipo'],$p['Fin']?:$p['Inicio'],$p['Inicio']])->fetchColumn())$errors[]=$e['Codigo'].': bloqueado por mantenimiento o indisponibilidad.';}
        if(!$p['Conductor'])$errors[]='Asignar conductor autorizado.';else{$driver=$this->run('SELECT * FROM Cx_Conductor WHERE IdEmpresa=? AND Usuario=?',[$company,$p['Conductor']])->fetch(PDO::FETCH_ASSOC);if(!$driver||$driver['VigenteHasta']<substr($p['Fin']?:$p['Inicio'],0,10))$errors[]='Documentación del conductor pendiente o vencida.';try{$this->opUser($company,$p['Conductor'],'DESPACHO');}catch(CxError $e){$errors[]=$e->getMessage();}}
        foreach($this->planBookings($p) as $b)if($this->run('SELECT IdReserva FROM Cx_ReservaRecurso WHERE IdEmpresa=? AND Tipo=? AND Recurso=? AND Activo=1 AND IdProgramacion<>? AND Inicio<? AND Fin>? LIMIT 1',[$company,$b[0],$b[1],$p['IdProgramacion'],$b[3],$b[2]])->fetchColumn())$errors[]='Solapamiento de '.$b[0].' '.$b[1].' entre '.$b[2].' y '.$b[3].'.';
        $materials=[];if($d)foreach($d['componentes'] as $c){$m=$this->material($company,$c['IdProducto']);$stock=$this->materialStock($company,$p['IdAlmacen'],$c['IdProducto']);$mine=$this->run('SELECT CantidadNominal FROM Cx_ReservaInsumo WHERE IdEmpresa=? AND IdProgramacion=? AND IdProducto=? AND Activo=1',[$company,$p['IdProgramacion'],$c['IdProducto']])->fetchColumn();$available=bcadd($stock['disponible'],$mine?:'0',6);$quantity=bcmul($c['CantidadNominal'],$p['Cantidad'],6);if($m['Unidad']!==$c['Unidad']||$m['BaseStock']!==$c['BaseDosificacion'])$errors[]='Unidad/base incompatible del insumo '.$m['Producto'].'.';if(bccomp($quantity,$available,6)>0)$errors[]='Insumo insuficiente: '.$m['Producto'].'. Disponible '.cxOpNumber($available).' '.$m['Unidad'].'; reserva nominal requerida '.cxOpNumber($quantity).'.';$shortage=bccomp($quantity,$available,6)>0?bcsub($quantity,$available,6):'0';$materials[]=['disponibleParaPedido'=>$available,'faltante'=>$shortage,'id'=>$c['IdProducto'],'nombre'=>$m['Producto'],'cantidadNominal'=>$quantity,'unidad'=>$m['Unidad'],'base'=>$m['BaseStock'],'stock'=>$stock];}
        return ['pendientes'=>array_values(array_unique($errors)),'materiales'=>$materials];
    }
    public function schedule($company,$id) {
        $p=$this->scheduleRow($company,$id);return array_merge($p,$this->scheduleRequirements($company,$p));
    }
    public function confirmSchedule($company,array $p) {
        $this->operational($company,'PROGRAMACION');$scope=$this->db->query('SELECT DATABASE()')->fetchColumn();$lock='imc_mov_'.substr(hash('sha256',$scope),0,40);if((int)$this->run('SELECT GET_LOCK(?,5)',[$lock])->fetchColumn()!==1)throw new CxError('Almacén está confirmando movimientos. Reintente.',409);
        try{return $this->atomic($company,function()use($company,$p){return $this->idempotency($company,'CONFIRMAR_AGENDA',$p['idempotencia']??'',[$p,$this->user],function()use($company,$p){$plan=$this->scheduleRow($company,$p['id']??0);if($plan['Estado']!=='BORRADOR'||(int)$plan['Revision']!==(int)($p['revision']??0))throw new CxError('La programación cambió o ya fue confirmada.',409);$requirements=$this->scheduleRequirements($company,$plan);if($requirements['pendientes'])throw new CxError(implode("\n",$requirements['pendientes']));foreach($this->planBookings($plan) as $b)$this->run('INSERT INTO Cx_ReservaRecurso(IdEmpresa,IdProgramacion,IdCarga,Tipo,Recurso,Inicio,Fin) VALUES(?,?,?,?,?,?,?)',[$company,$plan['IdProgramacion'],$b[4],$b[0],$b[1],$b[2],$b[3]]);foreach($requirements['materiales'] as $m)$this->run('INSERT INTO Cx_ReservaInsumo(IdEmpresa,IdProgramacion,IdAlmacen,IdProducto,CantidadNominal,Unidad,BaseStock) VALUES(?,?,?,?,?,?,?)',[$company,$plan['IdProgramacion'],$plan['IdAlmacen'],$m['id'],$m['cantidadNominal'],$m['unidad'],$m['base']]);$design=$this->design($company,$plan['IdDisenoVersion']);foreach($plan['cargas'] as $load){$snap=$load['Instantanea'];$snap['diseno']=$design;$snap['confirmacion']=['usuario'=>$this->user,'fecha'=>cxNow()];$this->run('UPDATE Cx_CargaProgramada SET Instantanea=? WHERE IdEmpresa=? AND IdCarga=?',[cxJson($snap),$company,$load['IdCarga']]);}$this->run("UPDATE Cx_Programacion SET Estado='CONFIRMADA' WHERE IdEmpresa=? AND IdProgramacion=?",[$company,$plan['IdProgramacion']]);$this->run("UPDATE Cx_CargaProgramada SET Estado='PROGRAMADA' WHERE IdEmpresa=? AND IdProgramacion=? AND RevisionPlan=?",[$company,$plan['IdProgramacion'],$plan['Revision']]);$this->audit($company,'programacion',$plan['IdProgramacion'],'CONFIRMAR_AGENDA',null,['reservasNominales'=>$requirements['materiales'],'usuario'=>$this->user,'noEsConsumo'=>true]);return ['id'=>$plan['IdProgramacion'],'estado'=>'CONFIRMADA'];});});}finally{$this->run('SELECT RELEASE_LOCK(?)',[$lock]);}
    }
    public function cancelSchedule($company,array $p) {
        $this->operational($company,'PROGRAMACION');return $this->atomic($company,function()use($company,$p){return $this->idempotency($company,'CANCELAR_AGENDA',$p['idempotencia']??'',[$p,$this->user],function()use($company,$p){$plan=$this->scheduleRow($company,$p['id']??0);if(!in_array($plan['Estado'],['BORRADOR','CONFIRMADA'],true)||(int)$plan['Revision']!==(int)($p['revision']??0))throw new CxError('La programación cambió o ya no es cancelable.',409);$this->assertUnstarted($plan);$reason=cxText($p['motivo']??'',3000,true);$this->releaseSchedule($company,$plan['IdProgramacion'],'CANCELADA');$this->audit($company,'programacion',$plan['IdProgramacion'],'CANCELAR',$plan,['reservasLiberadas'=>true,'sinReversarConsumos'=>true],$reason);return ['id'=>$plan['IdProgramacion'],'estado'=>'CANCELADA'];});});
    }
}
